use vstd::prelude::*;

verus! {

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        result@.len() == a@.len(),
        forall|i: int| 0 <= i < result@.len() ==> result@[i] == 1,
{
    let n: usize = a.len();
    let mut out: Vec<i32> = Vec::new();
    let mut i: usize = 0;

    while i < n
        invariant
            i <= n,
            out@.len() == i as int,
            forall|j: int| 0 <= j < out@.len() ==> out@[j] == 1,
            n == a@.len(), // keep a's length available in the loop
        decreases
            n - i,
    {
        out.push(1);
        i = i + 1;
    }

    out
}

} // verus!

